rule "Academy - Normalize GlobalProtect VPN Login"
when
  has_field("message") &&
  contains(to_string($message.message), "GLOBALPROTECT") &&
  contains(to_string($message.message), "globalprotect")
then
  let raw = to_string($message.message);
  let csv_match = regex(".*?(1,\\d{4}/\\d{2}/\\d{2}.*)", raw);
  let csv = to_string(csv_match["0"]);
  let parts = split(",", csv);

  let pan_type = to_string(parts[3]);
  let pan_subtype = to_string(parts[4]);
  let event_id = to_string(parts[8]);
  let gp_stage = to_string(parts[9]);
  let auth_method = to_string(parts[10]);
  let tunnel_type = to_string(parts[11]);
  let srcuser = to_string(parts[12]);
  let srcregion = to_string(parts[13]);
  let machine_name = to_string(parts[14]);
  let public_ip = to_string(parts[15]);
  let private_ip = to_string(parts[17]);
  let client_version = to_string(parts[21]);
  let client_os = to_string(parts[22]);
  let client_os_version = to_string(parts[23]);
  let gp_status = to_string(parts[28]);
  let gp_location = to_string(parts[29]);
  let portal = to_string(parts[33]);
  let gateway = to_string(parts[41]);
  let device_name = to_string(parts[47]);

  set_field("event_type", "vpn_login");
  set_field("event_category", "authentication");
  set_field("event_action", "login");
  set_field("event_outcome", gp_status);
  set_field("event_source", device_name);

  set_field("vendor", "Palo Alto Networks");
  set_field("product", "GlobalProtect");
  set_field("log_type", pan_type);
  set_field("vendor_subtype", pan_subtype);

  set_field("pan_event_id", event_id);
  set_field("pan_stage", gp_stage);
  set_field("auth_method", auth_method);
  set_field("tunnel_type", tunnel_type);
  set_field("vpn_type", tunnel_type);

  set_field("user_name", srcuser);
  set_field("srcuser", srcuser);

  set_field("source", device_name);
  set_field("source_ip", public_ip);
  set_field("public_ip", public_ip);
  set_field("private_ip", private_ip);

  set_field("machine_name", machine_name);
  set_field("machinename", machine_name);
  set_field("associated_assets", machine_name);

  set_field("portal", portal);
  set_field("gateway", gateway);

  set_field("client_version", client_version);
  set_field("client_os", client_os);
  set_field("client_os_version", client_os_version);

  set_field("source_geo_city_name", gp_location);
  set_field("source_geo_country_iso_code", srcregion);
  set_field("srcregion", srcregion);

  set_field("source", device_name);
end
